def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    aggressive_prev = []
    weak_opp_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) <= DAILY_SALARY * 1.2 or opp.get('hp', 0) <= 3:
                weak_opp_count += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
                if bid >= DAILY_SALARY * 0.9:
                    aggressive_prev.append(float(bid))

    if not alive_opponents:
        return float(min(budget, DAILY_SALARY * 0.25))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 0.55
    elif hp <= 4:
        urgency += 0.3
    if no_water_days >= 2:
        urgency += 0.35
    elif no_water_days == 1:
        urgency += 0.18
    urgency += scarcity * 0.28
    if day >= 8:
        urgency += 0.08
    if urgency > 1.0:
        urgency = 1.0

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
    elif supply >= 22 and hp >= 7 and no_water_days == 0:
        bid = DAILY_SALARY * 0.22
    elif supply <= 17:
        if aggressive_prev:
            bid = min(highest_prev + 1.5, DAILY_SALARY * 1.15)
        else:
            bid = DAILY_SALARY * (0.58 + 0.18 * urgency)
    else:
        anchor = max(avg_prev + 1.0, DAILY_SALARY * (0.38 + 0.32 * urgency))
        if highest_prev >= 120 and hp > 4 and no_water_days == 0:
            anchor = min(anchor, DAILY_SALARY * 0.42)
        bid = anchor

    if weak_opp_count >= 2 and hp >= 5 and no_water_days == 0:
        bid *= 0.9

    reserve_floor = DAILY_SALARY * (2.2 if hp > 3 else 1.0)
    max_affordable = budget
    if budget > reserve_floor:
        max_affordable = max(0.0, budget - reserve_floor + DAILY_SALARY * 0.75)

    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((agent_id, opp))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace only (immediate reaction)
    prev_bids = []
    prev_hp_after = []
    for agent_id, opp in alive_opps:
        pt = opp.get('previous_trace', None)
        if isinstance(pt, dict):
            b = pt.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                    prev_hp_after.append(float(pt.get('hp_after', opp.get('hp', 0.0))))
                except Exception:
                    pass

    # Supply pressure: with low supply, winning costs more; with high supply, can bid less.
    # Use a conservative mid-range targeting.
    if supply <= (MIN_SUPPLY + 1):
        supply_factor = 1.05
    elif supply >= (MAX_SUPPLY - 1):
        supply_factor = 0.85
    else:
        supply_factor = 0.95

    # Identify yesterday aggressor level
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid
    else:
        highest_prev_bid = 0.0
        second_prev_bid = 0.0

    # Determine our urgency
    urgency = 0
    if hp <= 2.0:
        urgency = 2
    elif hp <= 4.0:
        urgency = 1

    # If we are already accumulating no-water days, increase urgency.
    if no_water_days >= 2:
        urgency = max(urgency, 2)

    # Baseline bid: target just above the likely clearing price.
    # If Cindy/Alex were bidding near high levels, we shadow them; otherwise we undercut.
    # Use thresholds tied to DAILY_SALARY.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # High-pressure environment yesterday; shadow but cap by budget.
        target = max(DAILY_SALARY * 0.25, second_prev_bid + 2.0)
        if urgency >= 2:
            target = max(target, DAILY_SALARY * 0.55)
        else:
            target = max(target, DAILY_SALARY * 0.35)
    else:
        # Lower bids yesterday; we can bid moderately.
        target = max(DAILY_SALARY * 0.30, highest_prev_bid * 0.75 + 5.0)
        if urgency >= 2:
            target = max(target, DAILY_SALARY * 0.60)

    # Apply supply factor and small day-variant to avoid deterministic ties
    tie_break = 1.0 + (0.02 * (day % 5))
    target *= supply_factor * tie_break

    # Final cap: never exceed budget; also avoid extreme bids when not urgent.
    if urgency == 0:
        cap = DAILY_SALARY * 0.75
    elif urgency == 1:
        cap = DAILY_SALARY * 0.95
    else:
        cap = DAILY_SALARY * 1.10

    bid = float(min(budget, max(0.0, min(cap, target))))

    # Ensure at least a minimal competitive bid when we are alive and need water.
    if hp > 0 and bid < DAILY_SALARY * 0.15:
        bid = float(min(budget, DAILY_SALARY * 0.18))

    return bid

